"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["10458"],{57063(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.tipo_conceito.codigo_caractere_invalido","status":422,"titulo":"C\xf3digo do tipo de conceito cont\xe9m o caractere nulo ou caractere que n\xe3o \xe9 texto"},"descricao":{"codigo":"uniplus.configuracao.tipo_conceito.codigo_caractere_invalido","requisitos":[],"oQueAconteceu":["A cria\xe7\xe3o de um tipo de conceito (`POST /api/configuracao/admin/tipos-conceito`) trouxe um `codigo` com o caractere nulo (`U+0000`), um caractere de controle (como a quebra de linha ou a tabula\xe7\xe3o) ou de formata\xe7\xe3o, ou com texto que n\xe3o \xe9 Unicode v\xe1lido e, por isso, n\xe3o pode ser normalizado. A recusa evita que o c\xf3digo seja truncado, corrompido ou confundido com outro em sil\xeancio. Os espa\xe7os nas pontas s\xe3o desconsiderados antes da confer\xeancia.","O c\xf3digo do tipo de conceito n\xe3o tem formato fixo, ao contr\xe1rio do c\xf3digo de cada valor categ\xf3rico: fora o caractere inv\xe1lido, a regra \xe9 s\xf3 o tamanho m\xe1ximo ([c\xf3digo do tipo de conceito muito longo](/erros/uniplus.configuracao.tipo_conceito.codigo_tamanho)).","A recusa vem na lista `errors` da resposta, com `field` igual a `codigo`. As demais recusas do corpo v\xeam na mesma resposta, e nada \xe9 gravado. S\xf3 a cria\xe7\xe3o recebe o c\xf3digo: ele \xe9 imut\xe1vel e a atualiza\xe7\xe3o n\xe3o o aceita."],"comoResolver":["Remova o caractere inv\xe1lido do c\xf3digo e repita o pedido."],"ondeAparece":["Cria\xe7\xe3o de um tipo de conceito"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Tipo conceito"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"137e6bdd986deaebbd7281a2e43c40e18a247a98"}}')}}]);